diff --git i/internal/config/registries.go w/internal/config/registries.go
index 6e1cae10..4aede52a 100644
--- i/internal/config/registries.go
+++ w/internal/config/registries.go
@@ -77,6 +77,12 @@ func UsesCredentials(mode string) bool {
 	return mode != AuthAnonymous && mode != AuthInherit
 }

+// IsNexusGroup reports whether item is a group served by Nexus, the one kind of
+// group whose content can only be listed from the discovered-members cache.
+func IsNexusGroup(item RegistryItem) bool {
+	return item.Kind == KindGroup && item.Provider == ProviderNexus
+}
+
 // Providers returns the declared providers in the order a form cycles them,
 // generic first because it is the default for a group that says nothing.
 func Providers() []string {
diff --git i/internal/config/registries_test.go w/internal/config/registries_test.go
index 5a6c6107..0f9e8d84 100644
--- i/internal/config/registries_test.go
+++ w/internal/config/registries_test.go
@@ -598,3 +598,25 @@ func TestAConfigWithNoRepoPrefixStillLoads(t *testing.T) {
 		t.Errorf("repo prefix = %q, want nothing invented", items[0].RepoPrefix)
 	}
 }
+
+// DEVDESK-308: only a Nexus group lists from cached content.
+func TestIsNexusGroup(t *testing.T) {
+	tests := []struct {
+		name string
+		item RegistryItem
+		want bool
+	}{
+		{"nexus group", RegistryItem{Kind: KindGroup, Provider: ProviderNexus}, true},
+		{"harbor group", RegistryItem{Kind: KindGroup, Provider: ProviderHarbor}, false},
+		{"generic group", RegistryItem{Kind: KindGroup, Provider: ProviderGeneric}, false},
+		{"nexus plain registry", RegistryItem{Kind: KindRegistry, Provider: ProviderNexus}, false},
+		{"zero value", RegistryItem{}, false},
+	}
+	for _, tt := range tests {
+		t.Run(tt.name, func(t *testing.T) {
+			if got := IsNexusGroup(tt.item); got != tt.want {
+				t.Fatalf("IsNexusGroup(%+v) = %v, want %v", tt.item, got, tt.want)
+			}
+		})
+	}
+}
diff --git i/internal/ui/oci_resources/registry_browser.go w/internal/ui/oci_resources/registry_browser.go
index e8cdf057..c52d86ee 100644
--- i/internal/ui/oci_resources/registry_browser.go
+++ w/internal/ui/oci_resources/registry_browser.go
@@ -49,7 +49,11 @@ type browserRegistryEntry struct {
 	// for a member. It is what the result filter resolves labels through, and
 	// what replaced matching on URL — two registries configured with the same
 	// URL used to collide.
-	Slug        string
+	Slug string
+	// cachedOnly marks an entry whose content can only be listed from the
+	// discovered-members cache: a Nexus group, its members, or an entry that
+	// declares a Nexus group as its parent (DEVDESK-308).
+	cachedOnly  bool
 	ParentAlias string // non-empty = member of a group
 	ParentSlug  string
 	parentURL   string // URL of the parent RegistryItem (for credential lookup)
@@ -328,6 +332,10 @@ func newRegistryBrowser(
 func (b *RegistryBrowser) buildEntries(groups map[string]cache.RegistryGroupEntry, deselected map[string]bool) {
 	b.entries = nil
 	b.rows = nil
+	bySlug := make(map[string]config.RegistryItem, len(b.registries))
+	for _, reg := range b.registries {
+		bySlug[reg.Slug] = reg
+	}
 	for _, reg := range b.registries {
 		alias := browserAlias(reg)
 		// Members share their group's host and therefore its single credential
@@ -344,6 +352,7 @@ func (b *RegistryBrowser) buildEntries(groups map[string]cache.RegistryGroupEntr
 				URL: reg.URL, Alias: alias, Slug: reg.Slug, authMode: mode,
 				repoPrefix: reg.RepoPrefix,
 				key:        reg.Slug,
+				cachedOnly: listsCacheOnly(reg, bySlug),
 			})
 			continue
 		}
@@ -360,6 +369,7 @@ func (b *RegistryBrowser) buildEntries(groups map[string]cache.RegistryGroupEntr
 				ParentSlug:  reg.Slug,
 				parentURL:   reg.URL,
 				authMode:    mode,
+				cachedOnly:  config.IsNexusGroup(reg),
 				key:         memberKey(reg.Slug, m.URL, m.RepoPrefix),
 			})
 		}
@@ -371,6 +381,15 @@ func (b *RegistryBrowser) buildEntries(groups map[string]cache.RegistryGroupEntr
 	}
 }

+// listsCacheOnly reports whether reg can only be listed from the cache: it is a
+// Nexus group, or it declares a Nexus group as its parent (Q-B ii).
+func listsCacheOnly(reg config.RegistryItem, bySlug map[string]config.RegistryItem) bool {
+	if config.IsNexusGroup(reg) {
+		return true
+	}
+	return reg.Parent != "" && config.IsNexusGroup(bySlug[reg.Parent])
+}
+
 // memberKey names one member of a group. Scoping it by the group's slug is what
 // keeps two groups fronting the same repository apart, and what keeps a member
 // from colliding with a standalone registry keyed on its own slug.

