1	package ociresources
2	
3	import (
4		"fmt"
5		"math"
6		"strings"
7	
8		"charm.land/lipgloss/v2"
9		"github.com/charmbracelet/x/ansi"
10	
11		"github.com/anthnel/devdesk/internal/imagesearch"
12		"github.com/anthnel/devdesk/internal/ui/shortcut"
13		"github.com/anthnel/devdesk/internal/ui/theme"
14	)
15	
16	// noWidthLimit tells fitNames the header width is not known yet (before the first
17	// WindowSizeMsg): nothing is abbreviated.
18	const noWidthLimit = math.MaxInt
19	
20	// skippedHint explains a Skipped line; it is the first thing fitNames drops.
21	var skippedHint = fmt.Sprintf(" (type %d+ characters)", imagesearch.CatalogMinQueryRunes)
22	
23	// fitNames joins names with ", " and appends suffix, within width cells
24	// (ansi.StringWidth). It tries, in order, and returns the first that fits:
25	//  1. every name + suffix;
26	//  2. the first k names + ", +N" + suffix, k from len-1 down to 1;
27	//  3. "+N" + suffix (N = len(names));
28	//  4. steps 1 to 3 again without the suffix (only when suffix != "").
29	//
30	// When nothing fits it returns "+N" (wider than width: the header clips it).
31	// Empty names return "".
32	func fitNames(names []string, suffix string, width int) string {
33		if len(names) == 0 {
34			return ""
35		}
36		fits := func(s string) bool { return ansi.StringWidth(s) <= width }
37		try := func(suffix string) (string, bool) {
38			if all := strings.Join(names, ", ") + suffix; fits(all) {
39				return all, true
40			}
41			for k := len(names) - 1; k >= 1; k-- {
42				s := fmt.Sprintf("%s, +%d%s", strings.Join(names[:k], ", "), len(names)-k, suffix)
43				if fits(s) {
44					return s, true
45				}
46			}
47			if s := fmt.Sprintf("+%d%s", len(names), suffix); fits(s) {
48				return s, true
49			}
50			return "", false
51		}
52		if s, ok := try(suffix); ok {
53			return s
54		}
55		if suffix != "" {
56			if s, ok := try(""); ok {
57				return s
58			}
59		}
60		return fmt.Sprintf("+%d", len(names))
61	}
62	
63	// searchSummary is what the level 1 header says about the lot, names in form order.
64	type searchSummary struct {
65		Pending     int      // in the live lot, no answer yet
66		Interrupted []string // the lot was abandoned (→) before they answered
67		Failed      []string
68		Refused     []string
69		Partial     []string // ok or no result, cut at a cap
70		NoResult    []string // answered, nothing matches (Skipped excluded)
71		Skipped     []string // catalog not walked: query too short
72	}
73	
74	// summarizeSearch sorts the lot's keys into classes. Pure; names are label(key),
75	// in the order of keys.
76	func summarizeSearch(keys []string, outcomes map[string]imagesearch.Outcome, live bool,
77		label func(key string) string) searchSummary {
78		var s searchSummary
79		for _, k := range keys {
80			oc, ok := outcomes[k]
81			if !ok {
82				if live {
83					s.Pending++
84				} else {
85					s.Interrupted = append(s.Interrupted, label(k))
86				}
87				continue
88			}
89			switch oc.Verdict {
90			case imagesearch.VerdictFailed:
91				s.Failed = append(s.Failed, label(k))
92			case imagesearch.VerdictRefused:
93				s.Refused = append(s.Refused, label(k))
94			case imagesearch.VerdictNoResult:
95				if oc.Skipped {
96					s.Skipped = append(s.Skipped, label(k))
97					continue
98				}
99				s.NoResult = append(s.NoResult, label(k))
100				if oc.Partial {
101					s.Partial = append(s.Partial, label(k))
102				}
